styles:
pre.output {
      font-family: ui-monospace, monospace; font-size: .78rem;
      background: var(--is-bg-elev); border: 1px solid var(--is-border);
      border-radius: var(--is-radius); padding: .65rem .85rem;
      max-height: 14rem; overflow: auto;
      white-space: pre-wrap;
    }
    .kbd-hint {
      font-size: .78rem; color: var(--is-text-soft);
    }
    .kbd-hint kbd {
      font-family: ui-monospace, monospace; font-size: .72rem;
      padding: 1px 5px;
      border-radius: 4px;
      border: 1px solid var(--is-border);
      background: var(--is-bg-elev);
    }

